const data = $input.first().json.body;
const name = data.name;
const phone = data.phone;
const amount = Number(data.amount || 0);
const currentDebt = Number(data.current_debt || 0);
const creditLimit = Number(data.credit_limit || 0);
const type = data.type; // 'new_debt' or 'reminder'

const fmt = (n) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', minimumFractionDigits: 0 }).format(n);
const dateStr = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });

let message = '';
if (type === 'new_debt') {
  message += `Halo *${name}*,\n\n`;
  message += `Terima kasih telah berbelanja di *Warung Rafilah*.\n\n`;
  message += `Kami mencatat bon baru sebesar *${fmt(amount)}* pada tanggal ${dateStr}.\n`;
  message += `Sisa saldo bon Anda saat ini adalah *${fmt(currentDebt)}* (Batas Limit: ${fmt(creditLimit)}).\n\n`;
  message += `Salam hangat,\n*Warung Rafilah*`;
} else {
  message += `Halo *${name}*,\n\n`;
  message += `Ini adalah pengingat ramah untuk sisa saldo bon Anda di *Warung Rafilah* sebesar *${fmt(currentDebt)}* (Batas Limit: ${fmt(creditLimit)}).\n\n`;
  message += `Mohon dapat diselesaikan ketika ada waktu luang. Terima kasih banyak atas kepercayaan Anda!\n\n`;
  message += `Salam hangat,\n*Warung Rafilah*`;
}

// Format phone number for WAHA
let cleanPhone = phone;
if (!cleanPhone.endsWith('@g.us')) {
  cleanPhone = cleanPhone.replace(/[^0-9]/g, '');
  if (cleanPhone.startsWith('0')) {
    cleanPhone = '62' + cleanPhone.slice(1);
  }
  if (!cleanPhone.endsWith('@c.us')) {
    cleanPhone = cleanPhone + '@c.us';
  }
}

return [{ json: { chatId: cleanPhone, message } }];
